function t(s){return CURRENT_LANG==="da"?(DA[s]??s):s;}
function setLang(l){CURRENT_LANG=l;try{localStorage.setItem("cg_lang",l);}catch(e){}}
function syncLang(l){CURRENT_LANG=l;}
