function metamagicKnown(level){return level>=17?6:level>=10?4:level>=2?2:0;}
// Psi Warrior (Fighter) / Soulknife (Rogue) Psionic Energy Dice (PHB 2024 p.98/134) — identical progression, no player choice involved.
function psiEnergyDiceCount(level){return level>=17?12:level>=13?10:level>=9?8:level>=5?6:level>=3?4:0;}
function psiEnergyDieSize(level){return level>=17?"d12":level>=11?"d10":level>=5?"d8":"d6";}
