function expandPacks(list){return list.map(item=>PACK_CONTENTS[item]?item+" ("+PACK_CONTENTS[item].join(", ")+")":item);}
// Repair inventory text saved before pack contents existed: expand any bare pack name line that isn't already followed by its contents.
function repairPackLines(text){
  return(text||"").split("\n").map(line=>{
    const bullet=line.match(/^(\s*[•\-]?\s*)(.*)$/);
    const prefix=bullet?bullet[1]:"";const rest=bullet?bullet[2]:line;
    const contents=PACK_CONTENTS[rest.trim()];
    return contents?prefix+rest.trim()+" ("+contents.join(", ")+")":line;
  }).join("\n");
}
